<style>
.lmg-master-page{min-height:100vh;background:#f5f5f3;padding:20px}.lmg-master-page .card{border:1px solid #e4e4e7!important;border-radius:18px!important;background:#fff!important;box-shadow:0 1px 3px rgba(0,0,0,.05)!important;overflow:hidden}.lmg-master-page .card-header,.lmg-master-page .card-footer{background:#fff!important;border-color:#f4f4f5!important}.lmg-master-page .table{width:100%;border-collapse:collapse;color:#27272a}.lmg-master-page .table th{padding:13px 16px;background:#fafafa;border-bottom:1px solid #e4e4e7;font-size:10px;text-transform:uppercase;letter-spacing:.1em;color:#71717a}.lmg-master-page .table td{padding:14px 16px;border-bottom:1px solid #f4f4f5}.lmg-master-page .btn{display:inline-flex;align-items:center;justify-content:center;gap:6px;border:1px solid #e4e4e7;border-radius:10px;padding:8px 12px;background:#fff;color:#27272a;font-size:13px;font-weight:700;line-height:1.2;text-decoration:none;transition:.2s}.lmg-master-page .btn:hover{transform:translateY(-1px);box-shadow:0 4px 12px rgba(0,0,0,.08)}.lmg-master-page .btn-primary,.lmg-master-page .btn-dark{background:#18181b!important;border-color:#18181b!important;color:#fff!important}.lmg-master-page .btn-success{background:#bef264!important;border-color:#bef264!important;color:#18181b!important}.lmg-master-page .btn-danger,.lmg-master-page .btn-outline-danger{border-color:#fecdd3!important;background:#fff1f2!important;color:#be123c!important}.lmg-master-page .btn-warning,.lmg-master-page .btn-outline-warning{border-color:#fde68a!important;background:#fffbeb!important;color:#a16207!important}.lmg-master-page .form-control,.lmg-master-page .form-control-file{width:100%;border:1px solid #e4e4e7;border-radius:11px;background:#fafafa;padding:9px 12px;color:#27272a}.lmg-master-page .form-group{margin-bottom:16px}.lmg-master-page label{font-size:12px;font-weight:700;color:#52525b}.lmg-master-page .badge{display:inline-flex;border:1px solid #e4e4e7;border-radius:999px;background:#f4f4f5;padding:4px 8px;font-size:10px;font-weight:700;color:#52525b}.lmg-master-page .modal{position:fixed!important;inset:0!important;z-index:100000!important;display:none;overflow:auto;background:rgba(9,9,11,.65);padding:24px;backdrop-filter:blur(5px)}.lmg-master-page .modal.show{display:flex!important;align-items:flex-start;justify-content:center}.lmg-master-page .modal-dialog{width:100%;max-width:720px;margin:auto}.lmg-master-page .modal-lg{max-width:850px}.lmg-master-page .modal-xl{max-width:1180px}.lmg-master-page .modal-content{display:flex;max-height:calc(100vh - 48px);flex-direction:column;overflow:hidden;border:0!important;border-radius:22px!important;background:#fff;box-shadow:0 25px 60px rgba(0,0,0,.3)}.lmg-master-page .modal-header,.lmg-master-page .modal-footer{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:18px 22px;border-color:#f4f4f5}.lmg-master-page .modal-body{overflow:auto;padding:22px}.lmg-master-page .close{border:0;background:#f4f4f5;border-radius:10px;padding:5px 10px;font-size:22px;color:#71717a}.lmg-master-page .text-primary{color:#3f6212!important}.lmg-master-page .bg-light,.lmg-master-page .thead-light{background:#fafafa!important}@media(max-width:767px){.lmg-master-page{padding:12px}.lmg-master-page .table-responsive{overflow-x:auto}.lmg-master-page .modal{padding:10px}.lmg-master-page .modal-content{max-height:calc(100vh - 20px)}}
.lmg-master-page>.d-flex:first-of-type{border-radius:24px;background:#18181b;padding:24px 28px;color:#fff;box-shadow:0 12px 30px rgba(0,0,0,.12)}.lmg-master-page>.d-flex:first-of-type h1,.lmg-master-page>.d-flex:first-of-type .text-gray-800{color:#fff!important}.lmg-master-page>.d-flex:first-of-type .text-muted{color:#a1a1aa!important}.lmg-master-page .row{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.lmg-master-page [class*="col-"]{min-width:0}.lmg-master-page .d-flex,.lmg-master-page .form-inline{display:flex}.lmg-master-page .flex-column{flex-direction:column}.lmg-master-page .flex-wrap{flex-wrap:wrap}.lmg-master-page .align-items-center{align-items:center}.lmg-master-page .align-items-start{align-items:flex-start}.lmg-master-page .justify-content-between{justify-content:space-between}.lmg-master-page .justify-content-center{justify-content:center}.lmg-master-page .text-center{text-align:center}.lmg-master-page .text-right{text-align:right}.lmg-master-page .w-100{width:100%}.lmg-master-page .h-100{height:100%}.lmg-master-page .overflow-hidden{overflow:hidden}.lmg-master-page .text-decoration-none{text-decoration:none}.lmg-master-page .font-weight-bold{font-weight:700}.lmg-master-page .text-muted{color:#71717a}.lmg-master-page .text-gray-800{color:#27272a}.lmg-master-page .small{font-size:12px}.lmg-master-page .mb-0{margin-bottom:0}.lmg-master-page .mb-1{margin-bottom:4px}.lmg-master-page .mb-2{margin-bottom:8px}.lmg-master-page .mb-3{margin-bottom:12px}.lmg-master-page .mb-4{margin-bottom:20px}.lmg-master-page .mt-2{margin-top:8px}.lmg-master-page .mt-3{margin-top:12px}.lmg-master-page .mr-1{margin-right:4px}.lmg-master-page .mr-2{margin-right:8px}.lmg-master-page .ml-1{margin-left:4px}.lmg-master-page .ml-2{margin-left:8px}.lmg-master-page .p-3{padding:12px}.lmg-master-page .p-4{padding:16px}.lmg-master-page .py-3{padding-top:12px;padding-bottom:12px}.lmg-master-page .py-5{padding-top:36px;padding-bottom:36px}.lmg-master-page .px-3{padding-left:12px;padding-right:12px}.lmg-master-page .border{border:1px solid #e4e4e7!important}.lmg-master-page .rounded{border-radius:12px}.lmg-master-page .flex-fill{flex:1}.lmg-master-page hr{border:0;border-top:1px solid #e4e4e7}@media(max-width:1199px){.lmg-master-page .row{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:767px){.lmg-master-page .row{grid-template-columns:1fr}.lmg-master-page>.d-flex:first-of-type{padding:20px}.lmg-master-page .flex-md-row{flex-direction:column}.lmg-master-page .align-items-md-center{align-items:flex-start}}
</style>
<script>
document.addEventListener('DOMContentLoaded',()=>{
 const root=document.querySelector('.lmg-master-page');if(!root)return;
 const open=modal=>{if(!modal)return;modal.classList.add('show');document.body.style.overflow='hidden'};
 const close=modal=>{if(!modal)return;modal.classList.remove('show');if(!root.querySelector('.modal.show'))document.body.style.overflow=''};
 root.addEventListener('click',event=>{const trigger=event.target.closest('[data-toggle="modal"]');if(trigger){event.preventDefault();open(document.querySelector(trigger.dataset.target))}const dismiss=event.target.closest('[data-dismiss="modal"]');if(dismiss){event.preventDefault();close(dismiss.closest('.modal'))}if(event.target.classList.contains('modal'))close(event.target)});
});
</script>
